-- Arma2 Torneos — ERROR-CONTRACT-V1 ROLLBACK (not a migration; documented, never applied automatically).
-- GENERATED by backend/torneos/error-contract-v1/build-migration.mjs. Restores the 18 certified POST_0005 bodies byte for
-- byte (md5 pinned): the 23 RAISE statements get their legacy SQLSTATE back. Nothing else changes (no grant, no table).
-- Effect: expected domain errors answer 500 again and the three former 40001 raises re-enter PostgREST's retry loop;
-- the gateway's legacy-SQLSTATE defense still maps the 55000 / 54000 ones (not 40001). Order: DB rollback only when
-- the frontend/gateway no longer depend on the 4xx contract; the gateway defense can stay.
BEGIN;

CREATE TEMPORARY TABLE torneos_error_contract_v1_rollback_state (
  fn text PRIMARY KEY,
  attrs text NOT NULL
) ON COMMIT DROP;
CREATE TEMPORARY TABLE torneos_error_contract_v1_rollback_acl (
  authenticated_public integer NOT NULL,
  anon_public integer NOT NULL
) ON COMMIT DROP;

DO $pre$
DECLARE
  v_pins text[][] := array[
    array['public.append_tournament_playoff_phase(uuid,uuid,uuid,uuid,integer,boolean,uuid)', '996cb4f6fc49524fbda06f16227bc472', '1166ca6ba0811a83c688ed8c6d8c828c'],
    array['public.create_tournament_announcement_draft(uuid,uuid,uuid,text,text,text,text,text,text,timestamp with time zone,uuid,text,uuid)', '02eaa14aef6b3a9e709935e28232fe1b', 'f2f2dd910245f8ebb0c8ca2fd8448f19'],
    array['public.create_tournament_match_correction(uuid,uuid)', 'e951e5be55e80835906f355360398590', 'd0e27384efd5b70f5ef1baf9893ecf30'],
    array['public.request_tournament_match_correction(uuid,uuid,text)', '6cbfbe91fb54eafca64520456e700a1a', 'ea194c20129c58a1581ff0804ca362dd'],
    array['public.mark_tournament_suspension_served(uuid,uuid,text)', '179376cfb1cd940d64ffa7dc34c40dc6', '0ca29ae1d9e55671dc3cdd9d18d83efd'],
    array['public.protect_active_tournament_fixture_draft()', 'c067a91075ab2dd5f6b0d114b694286f', '4aef5269146750bfe579910f7772447f'],
    array['public.protect_tournament_completed_competition()', '94012caa5505b8845a21ea247d26a496', 'f3f77a153eab65aef37046c65b891698'],
    array['public.protect_tournament_match_squad_players()', 'd6a8eb923c378bbe47ceb4ee77a4f164', '517664b2b2e325b42af98731f5ec4366'],
    array['public.publish_tournament_announcement(uuid,integer)', '7b5de1040a89810b8a09055087d56519', 'e5e6d5e9c2e0acf73548209a0e265c80'],
    array['public.publish_tournament_fixture(uuid,uuid)', 'b730e3eda644554c36dca95eafb6bbce', '2c64761a38d28e5fbdcd5735fb0a76b2'],
    array['public.rebuild_tournament_standings(uuid,uuid,uuid,uuid,uuid,text,uuid)', '647d3a01d3489af7111afa6017e9dba3', '1cd1dbdabeae82ea7d6e0c9a7fce37c0'],
    array['public.record_manual_match_availability(uuid,uuid,uuid,text,text,text)', '63f7fb5c744586172f56043487225ca7', '1acdb4e53b05f3a8cb3c5a9b98bdfb3b'],
    array['public.resolve_tournament_qualification(uuid,text)', '3f1af0ba733eacf51bc868542c150c73', '193a69bf4fb8e95047015a9b9da3e9cd'],
    array['public.review_tournament_match_operation(uuid,uuid,text,text)', '6f5912e4cf6601ad1d8301ed61bf7adc', '840710c77dc6343c2232b4c6590c946f'],
    array['public.save_match_squad(uuid,uuid,uuid,jsonb)', 'b95278f07e0ce51fc297f3324ef1600a', '931d2820b0711135eb2365b50e95f303'],
    array['public.set_tournament_announcement_audience(uuid,text,uuid,uuid,uuid,uuid)', '9d00a52f2abea44a7d020f3db7a9ffe7', '7d7bbe6ba33b95a9fb601b3129b902d9'],
    array['public.set_tournament_announcement_link(uuid,text,uuid,text,text,integer)', 'b20a2f8a60d793fd8ab09ede3f7d7b4c', '8ff92a71f5efa6167556e5297f8b5cf1'],
    array['public.set_tournament_match_dual_control(uuid,uuid,boolean)', '0379096408e86030361fa2390fcf02b1', '631be35793594b6641529ded5b91c055']
  ];
  v_problems text[] := array[]::text[];
  v_md5 text;
  i integer;
BEGIN
  FOR i IN 1 .. array_length(v_pins, 1) LOOP
    SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure(v_pins[i][1]);
    IF v_md5 IS DISTINCT FROM v_pins[i][3] AND v_md5 IS DISTINCT FROM v_pins[i][2] THEN
      v_problems := v_problems || format('%s body %s is neither the ERROR-CONTRACT-V1 nor the POST_0005 body', v_pins[i][1], coalesce(v_md5, 'missing'));
    END IF;
  END LOOP;
  IF cardinality(v_problems) > 0 THEN
    RAISE EXCEPTION 'TORNEOS_ERROR_CONTRACT_V1_ROLLBACK_PRECONDITION_FAILED: %', array_to_string(v_problems, '; ');
  END IF;
  INSERT INTO torneos_error_contract_v1_rollback_state
  SELECT v_pins[k][1], concat_ws('|', pg_get_userbyid(p.proowner), coalesce(p.proacl::text, 'default'), p.prosecdef, coalesce(p.proconfig::text, ''),
                  p.provolatile, p.proparallel, p.proretset, p.prorettype::regtype, p.prokind, p.prolang)
  FROM generate_subscripts(v_pins, 1) k JOIN pg_proc p ON p.oid = to_regprocedure(v_pins[k][1]);
  INSERT INTO torneos_error_contract_v1_rollback_acl
  SELECT count(*) FILTER (WHERE has_function_privilege('authenticated', p.oid, 'EXECUTE')),
         count(*) FILTER (WHERE has_function_privilege('anon', p.oid, 'EXECUTE'))
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.prokind = 'f';
END $pre$;

-- public.append_tournament_playoff_phase(uuid,uuid,uuid,uuid,integer,boolean,uuid): POST_0005 body
CREATE OR REPLACE FUNCTION public.append_tournament_playoff_phase(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_phase_id uuid, p_qualifier_count integer, p_double_leg boolean, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_source_phase public.tournament_phases%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_sources jsonb := '[]'::jsonb;
  v_index integer;
  v_sequence integer;
  v_participant_count integer;
  v_previous_phase_count integer;
  v_previous_round_count integer;
  v_previous_match_count integer;
  v_round_count integer;
  v_match_count integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if p_qualifier_count not in (2, 4, 8, 16) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_QUALIFIERS';
  end if;

  if not (public.has_tournament_organization_capability(
    p_organization_id, 'fixture.publish'
  ) and public.has_tournament_season_access(p_organization_id, (select t.season_id from public.tournaments t where t.id = p_tournament_id and t.organization_id = p_organization_id))) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournaments tournament
    where tournament.id = p_tournament_id
      and tournament.organization_id = p_organization_id
      and tournament.status in ('completed', 'archived')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;

  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.publish', array['registration', 'scheduled', 'active']::text[]
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));

  select fixture.* into v_version
  from public.tournament_fixture_versions fixture
  where fixture.organization_id = p_organization_id
    and fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  for update;
  if v_version.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PUBLISHED_FIXTURE_REQUIRED';
  end if;

  select phase.* into v_phase
  from public.tournament_phases phase
  where phase.fixture_version_id = v_version.id
    and phase.configuration->>'appendOperationKey' = p_idempotency_key::text;
  if v_phase.id is not null then
    return jsonb_build_object(
      'tournamentId', p_tournament_id,
      'fixtureVersionId', v_version.id,
      'sourcePhaseId', v_phase.configuration->>'sourcePhaseId',
      'phaseId', v_phase.id,
      'status', 'published',
      'roundCount', (select count(*) from public.tournament_rounds where phase_id = v_phase.id),
      'matchCount', (select count(*) from public.tournament_matches where phase_id = v_phase.id)
    );
  end if;

  select phase.* into v_source_phase
  from public.tournament_phases phase
  where phase.id = p_source_phase_id
    and phase.organization_id = p_organization_id
    and phase.tournament_id = p_tournament_id
    and phase.category_id = p_category_id
    and phase.fixture_version_id = v_version.id
    and phase.phase_type = 'league'
    and phase.status <> 'archived'
  for share;
  if v_source_phase.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PLAYOFF_SOURCE_INVALID';
  end if;

  if exists (
    select 1 from public.tournament_phases phase
    where phase.fixture_version_id = v_version.id
      and phase.phase_type in (
        'round_of_32', 'round_of_16', 'quarterfinal',
        'semifinal', 'third_place', 'final', 'custom_knockout'
      )
      and phase.status <> 'archived'
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_PLAYOFF_PHASE_EXISTS';
  end if;

  select count(*) into v_participant_count
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_version.participant_set_id
    and participant.status = 'active';
  if p_qualifier_count > v_participant_count then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
  end if;

  select count(*) into v_previous_phase_count
  from public.tournament_phases where fixture_version_id = v_version.id;
  select count(*) into v_previous_round_count
  from public.tournament_rounds where fixture_version_id = v_version.id;
  select count(*) into v_previous_match_count
  from public.tournament_matches where fixture_version_id = v_version.id;
  select coalesce(max(phase.sequence_number), 0) + 1 into v_sequence
  from public.tournament_phases phase
  where phase.fixture_version_id = v_version.id;

  -- El builder distribuye la primera mitad en slots locales y la segunda en
  -- slots visitantes. Invertir esta última conserva el seeding 1-vs-N,
  -- 2-vs-(N-1), etc., sin hardcodear cruces ni materializar participantes.
  for v_index in 1..(p_qualifier_count / 2) loop
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'type', 'league_position',
      'phaseId', v_source_phase.id,
      'rankNumber', v_index
    ));
  end loop;
  for v_index in reverse p_qualifier_count..(p_qualifier_count / 2 + 1) loop
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'type', 'league_position',
      'phaseId', v_source_phase.id,
      'rankNumber', v_index
    ));
  end loop;

  insert into public.tournament_phases (
    organization_id, tournament_id, category_id, fixture_version_id,
    name, phase_type, sequence_number, status, configuration
  ) values (
    p_organization_id, p_tournament_id, p_category_id, v_version.id,
    'Playoffs', 'custom_knockout', v_sequence, 'generated',
    jsonb_build_object(
      'sourcePhaseId', v_source_phase.id,
      'qualifiers', p_qualifier_count,
      'seeding', 'league_ranking',
      'knockoutLegs', case when p_double_leg then 'double' else 'single' end,
      'appendOperationKey', p_idempotency_key
    )
  ) returning * into v_phase;

  perform public.build_tournament_knockout(
    v_version.id, v_phase.id, v_sources, coalesce(p_double_leg, false), false
  );

  select count(*) into v_round_count
  from public.tournament_rounds where phase_id = v_phase.id;
  select count(*) into v_match_count
  from public.tournament_matches where phase_id = v_phase.id;

  perform public.append_tournament_audit(
    p_organization_id, 'fixture.phase_appended', 'phase', v_phase.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'fixtureVersionId', v_version.id,
      'sourcePhaseId', v_source_phase.id,
      'qualifierCount', p_qualifier_count,
      'doubleLeg', coalesce(p_double_leg, false),
      'previousPhaseCount', v_previous_phase_count,
      'previousRoundCount', v_previous_round_count,
      'previousMatchCount', v_previous_match_count,
      'appendedRoundCount', v_round_count,
      'appendedMatchCount', v_match_count
    )
  );

  return jsonb_build_object(
    'tournamentId', p_tournament_id,
    'fixtureVersionId', v_version.id,
    'sourcePhaseId', v_source_phase.id,
    'phaseId', v_phase.id,
    'status', 'published',
    'roundCount', v_round_count,
    'matchCount', v_match_count
  );
end;
$function$;

-- public.create_tournament_announcement_draft(uuid,uuid,uuid,text,text,text,text,text,text,timestamp with time zone,uuid,text,uuid): POST_0005 body
CREATE OR REPLACE FUNCTION public.create_tournament_announcement_draft(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_announcement_type text, p_title text, p_summary text, p_body text, p_priority text, p_acknowledgement_mode text, p_scheduled_for timestamp with time zone, p_supersedes_id uuid, p_correction_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_existing public.tournament_announcements%rowtype;
  v_id uuid;
  v_version integer := 1;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if not (public.has_tournament_communications_capability(
    p_organization_id,'announcements.create'
  ) and public.has_tournament_season_access(p_organization_id, (select t.season_id from public.tournaments t where t.id = p_tournament_id and t.organization_id = p_organization_id))) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_category_id is not null and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_scheduled_for is not null
    and not (public.has_tournament_communications_capability(
      p_organization_id,'announcements.schedule'
    ) and public.has_tournament_season_access(p_organization_id, (select t.season_id from public.tournaments t where t.id = p_tournament_id and t.organization_id = p_organization_id)))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcements announcement
      where announcement.organization_id = p_organization_id
        and announcement.author_user_id = private.current_identity_id()
        and announcement.status in ('draft','scheduled')) >= 100
  then
    raise exception using errcode = '54000', message = 'TORNEOS_DRAFT_LIMIT_REACHED';
  end if;

  select * into v_existing
  from public.tournament_announcements announcement
  where announcement.organization_id = p_organization_id
    and announcement.author_user_id = private.current_identity_id()
    and announcement.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id <> p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.announcement_type <> p_announcement_type
      or v_existing.title <> btrim(p_title)
      or v_existing.summary <> btrim(p_summary)
      or v_existing.body <> btrim(p_body)
      or v_existing.priority <> coalesce(p_priority,'normal')
      or v_existing.acknowledgement_mode <> coalesce(p_acknowledgement_mode,'none')
      or v_existing.scheduled_for is distinct from p_scheduled_for
      or v_existing.supersedes_id is distinct from p_supersedes_id
      or v_existing.correction_reason is distinct from
        nullif(btrim(coalesce(p_correction_reason,'')),'')
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.id;
  end if;

  if p_supersedes_id is not null then
    select coalesce(max(announcement.version),0) + 1 into v_version
    from public.tournament_announcements announcement
    where announcement.id = p_supersedes_id
      and announcement.organization_id = p_organization_id
      and announcement.tournament_id = p_tournament_id
      and announcement.status = 'published';
    if v_version = 1
      or p_correction_reason is null
      or char_length(btrim(p_correction_reason)) < 4
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_CORRECTION';
    end if;
  end if;

  insert into public.tournament_announcements (
    organization_id,season_id,tournament_id,category_id,author_user_id,status,
    announcement_type,title,summary,body,priority,acknowledgement_mode,
    scheduled_for,version,supersedes_id,correction_reason,idempotency_key
  ) values (
    p_organization_id,v_tournament.season_id,p_tournament_id,p_category_id,
    private.current_identity_id(),case when p_scheduled_for is null then 'draft' else 'scheduled' end,
    p_announcement_type,btrim(p_title),btrim(p_summary),btrim(p_body),
    coalesce(p_priority,'normal'),coalesce(p_acknowledgement_mode,'none'),
    p_scheduled_for,v_version,p_supersedes_id,
    nullif(btrim(coalesce(p_correction_reason,'')),''),p_idempotency_key
  ) returning id into v_id;

  perform public.append_tournament_audit(
    p_organization_id,'communications.announcement_create','announcement',
    v_id,null,p_tournament_id,
    jsonb_build_object(
      'type',p_announcement_type,'scheduled',p_scheduled_for is not null,
      'supersedesId',p_supersedes_id
    )
  );
  return v_id;
end;
$function$;

-- public.create_tournament_match_correction(uuid,uuid): POST_0005 body
CREATE OR REPLACE FUNCTION public.create_tournament_match_correction(p_organization_id uuid, p_match_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source public.tournament_match_operations%rowtype;
  v_new public.tournament_match_operations%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-correction:' || p_match_operation_id, 0));
  select * into v_source from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_source.id is null or v_source.status <> 'official'
    or not exists (
      select 1
      from public.tournament_match_reviews review
      where review.match_operation_id = v_source.id
        and review.review_type = 'correction'
        and review.status = 'open'
    )
    or not (public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.correct'
    ) and public.has_tournament_season_access(p_organization_id, (select o.season_id from public.tournament_match_operations o where o.id = p_match_operation_id and o.organization_id = p_organization_id)))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations
    where source_operation_id = v_source.id and status <> 'voided'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_CORRECTION_EXISTS';
  end if;
  insert into public.tournament_match_operations (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    status, match_status, operation_version, source_operation_id,
    match_snapshot, home_team_snapshot, away_team_snapshot, notes,
    opened_by, reopened_at, reopened_by
  ) select
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    'draft', case (
      select outcome.outcome_type
      from public.tournament_match_outcomes outcome
      where outcome.match_operation_id = v_source.id
    )
      when 'played' then 'played'
      when 'suspended' then 'suspended'
      when 'abandoned' then 'abandoned'
      when 'home_no_show' then 'administrative'
      when 'away_no_show' then 'administrative'
      when 'double_no_show' then 'administrative'
      when 'walkover_home' then 'administrative'
      when 'walkover_away' then 'administrative'
      when 'administrative_result' then 'administrative'
      else 'ready'
    end,
    (
      select coalesce(max(existing.operation_version), 0) + 1
      from public.tournament_match_operations existing
      where existing.match_id = v_source.match_id
    ), id, match_snapshot, home_team_snapshot,
    away_team_snapshot, notes, private.current_identity_id(), now(), private.current_identity_id()
  from public.tournament_match_operations where id = v_source.id
  returning * into v_new;
  insert into public.tournament_match_operation_players (
    organization_id, match_operation_id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  ) select
    organization_id, v_new.id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  from public.tournament_match_operation_players where match_operation_id = v_source.id;
  insert into public.tournament_match_outcomes (
    match_operation_id, organization_id, match_id, outcome_type, started_at,
    ended_at, suspension_minute, suspension_period, events_remain_valid,
    reason_code, reason_text, administrative_home_score, administrative_away_score,
    counts_for_standings, counts_for_player_stats, requires_resolution,
    resolved_by, resolved_at
  ) select
    v_new.id, organization_id, match_id, outcome_type, started_at, ended_at,
    suspension_minute, suspension_period, events_remain_valid, reason_code,
    reason_text, administrative_home_score, administrative_away_score,
    counts_for_standings, counts_for_player_stats, requires_resolution,
    resolved_by, resolved_at
  from public.tournament_match_outcomes where match_operation_id = v_source.id;
  insert into public.tournament_match_scores (
    match_operation_id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  ) select
    v_new.id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  from public.tournament_match_scores where match_operation_id = v_source.id;
  insert into public.tournament_match_events (
    organization_id, match_operation_id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, event_type, minute, period,
    sequence_number, unidentified_player_reason, metadata, created_by
  ) select
    organization_id, v_new.id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, event_type, minute, period,
    sequence_number, unidentified_player_reason,
    metadata || jsonb_build_object(
      'copiedFromEventId', id,
      'copiedFromRelatedEventId', related_event_id
    ), private.current_identity_id()
  from public.tournament_match_events
  where match_operation_id = v_source.id and voided_at is null
  order by sequence_number;
  update public.tournament_match_events copied
  set related_event_id = copied_goal.id
  from public.tournament_match_events copied_goal
  where copied.match_operation_id = v_new.id
    and copied.event_type in ('assist', 'substitution_in')
    and copied_goal.match_operation_id = v_new.id
    and copied_goal.metadata->>'copiedFromEventId'
      = copied.metadata->>'copiedFromRelatedEventId';
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.correction_created',
    'match_operation', v_new.id, null, v_new.tournament_id,
    jsonb_build_object(
      'sourceOperationId', v_source.id,
      'operationVersion', v_new.operation_version
    )
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_new.id);
end;
$function$;

-- public.request_tournament_match_correction(uuid,uuid,text): POST_0005 body
CREATE OR REPLACE FUNCTION public.request_tournament_match_correction(p_organization_id uuid, p_match_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'official'
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 2000
    or not (public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.request_correction'
    ) and public.has_tournament_season_access(p_organization_id, (select o.season_id from public.tournament_match_operations o where o.id = p_match_operation_id and o.organization_id = p_organization_id)))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1
    from public.tournament_match_reviews review
    where review.match_operation_id = v_operation.id
      and review.review_type = 'correction'
      and review.status = 'open'
  ) then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_CORRECTION_EXISTS';
  end if;
  insert into public.tournament_match_reviews (
    organization_id, match_operation_id, review_type, reason, requested_by
  ) values (
    p_organization_id, v_operation.id, 'correction', btrim(p_reason), private.current_identity_id()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.correction_requested',
    'match_operation', v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$;

-- public.mark_tournament_suspension_served(uuid,uuid,text): POST_0005 body
CREATE OR REPLACE FUNCTION public.mark_tournament_suspension_served(p_suspension_id uuid, p_match_id uuid, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_suspension public.tournament_player_suspensions%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  if v_suspension.id is null or not (public.has_tournament_organization_capability(
    v_suspension.organization_id, 'suspensions.mark_served'
  ) and public.has_tournament_season_access(v_suspension.organization_id, (select t.season_id from public.tournaments t where t.id = v_suspension.tournament_id))) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_suspension.organization_id::text || ':' || v_suspension.tournament_id::text || ':'
    || v_suspension.category_id::text || ':' || v_suspension.phase_id::text || ':'
    || coalesce(v_suspension.group_id::text, 'all'),
    0
  ));
  select * into strict v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id for update;
  if v_suspension.status not in ('active', 'reduced') then
    if v_suspension.status = 'served' then return v_suspension.id; end if;
    raise exception using errcode = '55000', message = 'TORNEOS_SUSPENSION_NOT_ACTIVE';
  end if;
  if not exists (
    select 1
    from public.tournament_matches match_row
    join public.tournament_competition_participants home
      on home.id = match_row.home_participant_id
    join public.tournament_competition_participants away
      on away.id = match_row.away_participant_id
    join public.tournament_match_operations operation
      on operation.match_id = match_row.id and operation.status = 'official'
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = operation.id
      and outcome.counts_for_standings
    where match_row.id = p_match_id
      and match_row.organization_id = v_suspension.organization_id
      and match_row.tournament_id = v_suspension.tournament_id
      and match_row.id is distinct from v_suspension.source_match_id
      and v_suspension.team_entry_id in (home.team_entry_id, away.team_entry_id)
      and (
        (
          v_suspension.source_match_id is null
          and operation.official_at > v_suspension.created_at
        )
        or exists (
          select 1
          from public.tournament_match_operations source_operation
          where source_operation.match_id = v_suspension.source_match_id
            and source_operation.status in ('official', 'superseded')
            and operation.official_at > source_operation.official_at
        )
      )
      and not exists (
        select 1 from public.tournament_match_operation_players operation_player
        where operation_player.match_operation_id = operation.id
          and operation_player.roster_player_id = v_suspension.roster_player_id
          and operation_player.attendance_status not in ('absent', 'excused')
      )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_SUSPENSION_MATCH_INVALID';
  end if;

  insert into public.tournament_suspension_served_matches (
    suspension_id, organization_id, match_id, marked_by, note
  ) values (
    v_suspension.id, v_suspension.organization_id, p_match_id, private.current_identity_id(), p_note
  ) on conflict (suspension_id, match_id) do nothing;

  update public.tournament_player_suspensions suspension
  set served_matches = least(total_matches, (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    )),
    status = case when (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    ) >= total_matches then 'served' else status end,
    updated_at = now()
  where suspension.id = v_suspension.id;

  perform public.append_tournament_audit(
    v_suspension.organization_id, 'suspension.mark_served', 'player_suspension',
    v_suspension.id, v_suspension.team_entry_id, v_suspension.tournament_id,
    jsonb_build_object('matchId', p_match_id, 'note', p_note)
  );
  return v_suspension.id;
end;
$function$;

-- public.protect_active_tournament_fixture_draft(): POST_0005 body
CREATE OR REPLACE FUNCTION public.protect_active_tournament_fixture_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_fixture_version_id uuid;
  v_fixture_status text;
  v_tournament_status text;
begin
  v_fixture_version_id := case
    when tg_op = 'DELETE' then old.fixture_version_id
    else new.fixture_version_id
  end;

  select fixture.status, tournament.status
  into v_fixture_status, v_tournament_status
  from public.tournament_fixture_versions fixture
  join public.tournaments tournament on tournament.id = fixture.tournament_id
  where fixture.id = v_fixture_version_id;

  if v_fixture_status = 'draft'
    and v_tournament_status not in ('registration', 'scheduled')
  then
    raise exception using errcode = '55000',
      message = 'TORNEOS_FIXTURE_DRAFT_READ_ONLY';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

-- public.protect_tournament_completed_competition(): POST_0005 body
CREATE OR REPLACE FUNCTION public.protect_tournament_completed_competition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb;
  v_tournament_id uuid;
  v_match_id uuid;
  v_operation_id uuid;
  v_status text;
begin
  v_row := coalesce(to_jsonb(new), to_jsonb(old));
  v_tournament_id := nullif(v_row->>'tournament_id', '')::uuid;

  if v_tournament_id is null then
    v_match_id := nullif(v_row->>'match_id', '')::uuid;
    if v_match_id is not null then
      select match_row.tournament_id into v_tournament_id
      from public.tournament_matches match_row
      where match_row.id = v_match_id;
    end if;
  end if;

  if v_tournament_id is null then
    v_operation_id := nullif(v_row->>'match_operation_id', '')::uuid;
    if v_operation_id is not null then
      select operation.tournament_id into v_tournament_id
      from public.tournament_match_operations operation
      where operation.id = v_operation_id;
    end if;
  end if;

  if v_tournament_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  select tournament.status into v_status
  from public.tournaments tournament
  where tournament.id = v_tournament_id;

  if v_status in ('completed', 'archived') then
    raise exception using errcode = '22023',
      message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

-- public.protect_tournament_match_squad_players(): POST_0005 body
CREATE OR REPLACE FUNCTION public.protect_tournament_match_squad_players()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_squad_status text;
begin
  select status into v_squad_status
  from public.tournament_match_squads
  where id = coalesce(new.match_squad_id, old.match_squad_id);
  if v_squad_status is distinct from 'draft' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_SQUAD_LOCKED';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

-- public.publish_tournament_announcement(uuid,integer): POST_0005 body
CREATE OR REPLACE FUNCTION public.publish_tournament_announcement(p_announcement_id uuid, p_expected_recipient_count integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_count integer;
  v_snapshot jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if v_announcement.id is null
    or not (public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.publish'
    ) and public.has_tournament_season_access(v_announcement.organization_id, v_announcement.season_id))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if v_announcement.status = 'published' then
    return jsonb_build_object(
      'announcementId',v_announcement.id,
      'status','published',
      'recipientCount',v_announcement.published_recipient_count,
      'audienceChanged',false
    );
  end if;
  if v_announcement.status not in ('draft','scheduled') then
    raise exception using errcode = '23514', message = 'TORNEOS_COMMUNICATION_NOT_PUBLISHABLE';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_announcement.organization_id::text,731)
  );
  if (select count(*) from public.tournament_announcements announcement
      where announcement.organization_id = v_announcement.organization_id
        and announcement.status in ('published','superseded','archived','revoked')
        and announcement.published_at >= now() - interval '1 hour') >= 20
  then
    raise exception using errcode = '54000', message = 'TORNEOS_PUBLISH_RATE_LIMITED';
  end if;
  if not exists (
    select 1 from public.tournament_announcement_audiences audience
    where audience.announcement_id = p_announcement_id
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_AUDIENCE_REQUIRED';
  end if;
  if exists (
    select 1
    from public.tournament_announcement_links link
    where link.announcement_id = p_announcement_id
      and (
        (link.link_type = 'category' and not exists (
          select 1
          from public.tournament_categories category
          where category.id = link.resource_id
            and category.organization_id = v_announcement.organization_id
            and category.tournament_id = v_announcement.tournament_id
            and category.status = 'active'
        ))
        or (link.link_type = 'match' and not exists (
          select 1
          from public.tournament_matches match
          join public.tournament_fixture_versions fixture
            on fixture.organization_id = match.organization_id
           and fixture.id = match.fixture_version_id
           and fixture.status = 'published'
          where match.id = link.resource_id
            and match.organization_id = v_announcement.organization_id
            and match.tournament_id = v_announcement.tournament_id
        ))
        or (link.link_type = 'document' and not exists (
          select 1
          from public.tournament_documents document
          where document.id = link.resource_id
            and document.organization_id = v_announcement.organization_id
            and document.tournament_id = v_announcement.tournament_id
            and document.status = 'published'
        ))
      )
  ) then
    raise exception using errcode = '42501',
      message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  select count(*) into v_count
  from public.resolve_tournament_announcement_recipients(p_announcement_id);
  if v_count = 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_AUDIENCE_EMPTY';
  end if;
  if v_count > 5000 then
    raise exception using errcode = '54000', message = 'TORNEOS_RECIPIENT_LIMIT_REACHED';
  end if;
  select jsonb_build_object(
    'criteria',coalesce(jsonb_agg(jsonb_build_object(
      'type',audience.audience_type,
      'categoryId',audience.category_id,
      'teamEntryId',audience.team_entry_id,
      'matchId',audience.match_id
    ) order by audience.created_at,audience.id),'[]'::jsonb),
    'recipientCount',v_count,
    'resolvedAt',now()
  ) into v_snapshot
  from public.tournament_announcement_audiences audience
  where audience.announcement_id = p_announcement_id;

  insert into public.tournament_announcement_deliveries (
    organization_id,announcement_id,recipient_user_id,recipient_relation_type
  )
  select v_announcement.organization_id,p_announcement_id,user_id,relation_type
  from public.resolve_tournament_announcement_recipients(p_announcement_id)
  on conflict (announcement_id,recipient_user_id) do nothing;

  if v_announcement.supersedes_id is not null then
    update public.tournament_announcements
    set status = 'superseded'
    where id = v_announcement.supersedes_id
      and organization_id = v_announcement.organization_id
      and tournament_id = v_announcement.tournament_id
      and status = 'published';
    if not found then
      raise exception using errcode = '40001',
        message = 'TORNEOS_CORRECTION_ALREADY_SUPERSEDED';
    end if;
  end if;
  update public.tournament_announcements
  set status = 'published',published_at = now(),scheduled_for = null,
    published_recipient_count = v_count,audience_snapshot = v_snapshot
  where id = p_announcement_id;

  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_publish','announcement',
    p_announcement_id,null,v_announcement.tournament_id,
    jsonb_build_object(
      'recipientCount',v_count,
      'previewCount',p_expected_recipient_count,
      'audienceChanged',p_expected_recipient_count is not null
        and p_expected_recipient_count <> v_count,
      'channel','internal_only'
    )
  );
  return jsonb_build_object(
    'announcementId',p_announcement_id,'status','published',
    'recipientCount',v_count,
    'audienceChanged',p_expected_recipient_count is not null
      and p_expected_recipient_count <> v_count
  );
end;
$function$;

-- public.publish_tournament_fixture(uuid,uuid): POST_0005 body
CREATE OR REPLACE FUNCTION public.publish_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_previous public.tournament_fixture_versions%rowtype;
  v_validation jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status = 'draft'
  for update;
  if v_version.id is null
    or not (public.has_tournament_organization_capability(p_organization_id, 'fixture.publish') and public.has_tournament_season_access(p_organization_id, (select v.season_id from public.tournament_fixture_versions v where v.id = p_fixture_version_id and v.organization_id = p_organization_id)))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform public.assert_tournament_fixture_scope(
    p_organization_id, v_version.tournament_id, v_version.category_id,
    'fixture.publish', array['registration', 'scheduled']::text[]
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || v_version.tournament_id::text || ':' || v_version.category_id::text, 0
  ));
  if exists (
    select 1
    from public.tournament_fixture_versions newer
    where newer.tournament_id = v_version.tournament_id
      and newer.category_id = v_version.category_id
      and newer.status = 'draft'
      and newer.version_number > v_version.version_number
  ) then
    raise exception using errcode = '40001', message = 'TORNEOS_STALE_FIXTURE_VERSION';
  end if;
  v_validation := public.validate_tournament_fixture(p_organization_id, v_version.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_FIXTURE_INVALID';
  end if;
  select version.* into v_previous
  from public.tournament_fixture_versions version
  where version.tournament_id = v_version.tournament_id
    and version.category_id = v_version.category_id
    and version.status = 'published'
  for update;
  if v_previous.id is not null then
    if not (public.has_tournament_organization_capability(
      p_organization_id, 'fixture.supersede'
    ) and public.has_tournament_season_access(p_organization_id, (select v.season_id from public.tournament_fixture_versions v where v.id = p_fixture_version_id and v.organization_id = p_organization_id))) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    update public.tournament_fixture_versions
    set status = 'superseded', superseded_at = now()
    where id = v_previous.id;
    perform public.append_tournament_audit(
      p_organization_id, 'fixture.superseded', 'fixture_version', v_previous.id,
      null, v_version.tournament_id,
      jsonb_build_object('supersededByFixtureVersionId', v_version.id)
    );
  end if;
  update public.tournament_fixture_versions
  set status = 'published', published_at = now()
  where id = v_version.id;
  update public.tournament_rounds round_row
  set status = case
      when not exists (
        select 1 from public.tournament_matches match_row
        where match_row.round_id = round_row.id
          and match_row.status not in ('scheduled', 'ready', 'cancelled')
      ) then 'scheduled'
      else 'draft'
    end
  where round_row.fixture_version_id = v_version.id
    and round_row.status <> 'locked';
  update public.tournament_phases phase
  set status = case
      when not exists (
        select 1 from public.tournament_matches match_row
        where match_row.phase_id = phase.id
          and match_row.status not in ('scheduled', 'ready', 'cancelled')
      ) then 'scheduled'
      else 'generated'
    end
  where phase.fixture_version_id = v_version.id;
  update public.tournaments
  set status = 'scheduled'
  where id = v_version.tournament_id
    and organization_id = p_organization_id
    and status = 'registration';
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.published', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object(
      'categoryId', v_version.category_id,
      'versionNumber', v_version.version_number,
      'previousFixtureVersionId', v_previous.id
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'status', 'published',
    'supersededFixtureVersionId', v_previous.id
  );
end;
$function$;

-- public.rebuild_tournament_standings(uuid,uuid,uuid,uuid,uuid,text,uuid): POST_0005 body
CREATE OR REPLACE FUNCTION public.rebuild_tournament_standings(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid, p_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_revision public.tournament_standings_revisions%rowtype;
  v_existing_draft public.tournament_standings_revisions%rowtype;
  v_fixture public.tournament_fixture_versions%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_scoring public.tournament_scoring_rules%rowtype;
  v_discipline public.tournament_discipline_rules%rowtype;
  v_number integer;
  v_fingerprint text;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not (public.has_tournament_organization_capability(
    p_organization_id, 'standings.rebuild'
  ) and public.has_tournament_season_access(p_organization_id, (select t.season_id from public.tournaments t where t.id = p_tournament_id and t.organization_id = p_organization_id))) then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  if p_idempotency_key is null or char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_REASON_REQUIRED';
  end if;

  select * into v_revision
  from public.tournament_standings_revisions
  where organization_id = p_organization_id
    and calculated_by = private.current_identity_id()
    and idempotency_key = p_idempotency_key;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || p_tournament_id::text || ':'
    || p_category_id::text || ':' || p_phase_id::text || ':'
    || coalesce(p_group_id::text, 'all'),
    0
  ));

  select fixture.* into v_fixture
  from public.tournament_fixture_versions fixture
  join public.tournaments tournament
    on tournament.organization_id = fixture.organization_id
    and tournament.id = fixture.tournament_id
  where fixture.organization_id = p_organization_id
    and fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and tournament.status <> 'archived'
  for update of fixture;
  if v_fixture.id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_SCOPE_INVALID';
  end if;

  select * into v_phase from public.tournament_phases
  where organization_id = p_organization_id
    and tournament_id = p_tournament_id
    and category_id = p_category_id
    and fixture_version_id = v_fixture.id
    and id = p_phase_id
  for share;
  if v_phase.id is null or (
    p_group_id is not null and not exists (
      select 1 from public.tournament_groups group_row
      where group_row.id = p_group_id
        and group_row.organization_id = p_organization_id
        and group_row.tournament_id = p_tournament_id
        and group_row.category_id = p_category_id
        and group_row.fixture_version_id = v_fixture.id
        and group_row.phase_id = p_phase_id
        and group_row.status = 'published'
    )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_SCOPE_INVALID';
  end if;

  if v_revision.id is not null then
    if v_revision.tournament_id <> p_tournament_id
      or v_revision.category_id <> p_category_id
      or v_revision.fixture_version_id <> v_fixture.id
      or v_revision.phase_id <> p_phase_id
      or v_revision.group_id is distinct from p_group_id
      or v_revision.rebuild_reason <> btrim(p_reason)
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_revision.id;
  end if;

  select * into strict v_scoring from public.tournament_scoring_rules
  where tournament_id = p_tournament_id for share;
  select * into strict v_discipline from public.tournament_discipline_rules
  where tournament_id = p_tournament_id for share;
  perform 1
  from public.tournament_tiebreak_rules rule
  where rule.tournament_id = p_tournament_id
  order by rule.sort_order
  for share;

  perform 1
  from public.tournament_matches match_row
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id
  where match_row.fixture_version_id = v_fixture.id
    and (
      (
        match_row.phase_id = p_phase_id
        and match_row.group_id is not distinct from p_group_id
      )
      or match_phase.sequence_number < v_phase.sequence_number
    )
  order by match_row.match_number, operation.id
  for share of match_row, operation, outcome;
  perform 1
  from public.tournament_match_operation_players operation_player
  join public.tournament_match_operations operation
    on operation.id = operation_player.match_operation_id
    and operation.status = 'official'
  join public.tournament_matches match_row on match_row.id = operation.match_id
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  where match_row.fixture_version_id = v_fixture.id
    and (
      (
        match_row.phase_id = p_phase_id
        and match_row.group_id is not distinct from p_group_id
      )
      or match_phase.sequence_number < v_phase.sequence_number
    )
  order by operation_player.match_operation_id, operation_player.roster_player_id
  for share of operation_player;
  perform 1
  from public.tournament_match_events event
  join public.tournament_match_operations operation
    on operation.id = event.match_operation_id and operation.status = 'official'
  join public.tournament_matches match_row on match_row.id = operation.match_id
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  where match_row.fixture_version_id = v_fixture.id
    and (
      (
        match_row.phase_id = p_phase_id
        and match_row.group_id is not distinct from p_group_id
      )
      or match_phase.sequence_number < v_phase.sequence_number
    )
  order by event.match_operation_id, event.sequence_number
  for share of event;
  perform 1
  from public.tournament_points_adjustments adjustment
  where adjustment.fixture_version_id = v_fixture.id
    and adjustment.phase_id = p_phase_id
    and adjustment.group_id is not distinct from p_group_id
  order by adjustment.id
  for share;

  v_fingerprint := public.tournament_projection_source_fingerprint(
    v_fixture.id, p_phase_id, p_group_id
  );

  select * into v_existing_draft
  from public.tournament_standings_revisions
  where fixture_version_id = v_fixture.id and phase_id = p_phase_id
    and group_id is not distinct from p_group_id and status = 'draft'
  for update;
  if v_existing_draft.id is not null then
    if v_existing_draft.source_fingerprint = v_fingerprint then
      raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_DRAFT_EXISTS';
    end if;
    update public.tournament_standings_revisions
    set status = 'discarded', discarded_by = private.current_identity_id(), discarded_at = now(),
      discard_reason = 'Las fuentes oficiales cambiaron antes de la publicación.'
    where id = v_existing_draft.id;
    perform public.append_tournament_audit(
      p_organization_id, 'standings.discard_stale', 'standings_revision',
      v_existing_draft.id, null, p_tournament_id,
      jsonb_build_object(
        'previousFingerprint', v_existing_draft.source_fingerprint,
        'currentFingerprint', v_fingerprint
      )
    );
  end if;

  select coalesce(max(revision_number), 0) + 1 into v_number
  from public.tournament_standings_revisions
  where fixture_version_id = v_fixture.id and phase_id = p_phase_id
    and group_id is not distinct from p_group_id;
  insert into public.tournament_standings_revisions (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, group_id, revision_number, source_fingerprint,
    configuration_snapshot, rebuild_reason, calculated_by, idempotency_key
  ) values (
    p_organization_id, v_fixture.season_id, p_tournament_id, p_category_id,
    v_fixture.id, p_phase_id, p_group_id, v_number, v_fingerprint,
    jsonb_build_object(
      'scoring', to_jsonb(v_scoring) - 'created_at' - 'updated_at',
      'tiebreaks', coalesce((
        select jsonb_agg(jsonb_build_object(
          'criterion', criterion, 'order', sort_order
        ) order by sort_order)
        from public.tournament_tiebreak_rules where tournament_id = p_tournament_id
      ), '[]'::jsonb),
      'discipline', to_jsonb(v_discipline) - 'created_at' - 'updated_at',
      'algorithmVersion', 2
    ),
    btrim(p_reason), private.current_identity_id(), p_idempotency_key
  ) returning * into v_revision;

  insert into public.tournament_projection_sources (
    revision_id, organization_id, match_operation_id, match_id, official_at
  )
  select v_revision.id, p_organization_id, operation.id, match_row.id, operation.official_at
  from public.tournament_matches match_row
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id
  where match_row.fixture_version_id = v_fixture.id
    and match_row.phase_id = p_phase_id
    and match_row.group_id is not distinct from p_group_id
    and (outcome.counts_for_standings or outcome.counts_for_player_stats);

  insert into public.tournament_team_standings (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    participant_id, team_entry_id, played, won, drawn, lost, goals_for,
    goals_against, goal_difference, base_points, points_adjustment, points,
    walkovers, administrative_results, fair_play_points
  )
  with participants as (
    select participant.id, participant.team_entry_id
    from public.tournament_competition_participants participant
    where participant.participant_set_id = v_fixture.participant_set_id
      and participant.status in ('active', 'withdrawn')
      and (
        p_group_id is null
        or exists (
          select 1 from public.tournament_group_members member
          where member.group_id = p_group_id and member.participant_id = participant.id
        )
      )
  ), team_matches as (
    select match_row.home_participant_id as participant_id,
      score.home_score::integer as gf, score.away_score::integer as ga,
      outcome.outcome_type
    from public.tournament_projection_sources source
    join public.tournament_matches match_row on match_row.id = source.match_id
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    join public.tournament_match_scores score
      on score.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_standings
    union all
    select match_row.away_participant_id, score.away_score::integer,
      score.home_score::integer, outcome.outcome_type
    from public.tournament_projection_sources source
    join public.tournament_matches match_row on match_row.id = source.match_id
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    join public.tournament_match_scores score
      on score.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_standings
  ), cards as (
    select event.team_entry_id,
      sum(case
        when event.event_type = 'yellow_card' then v_discipline.yellow_fair_play_points
        when event.event_type = 'second_yellow'
          then case when v_discipline.double_yellow_counts_as_red
            then v_discipline.red_fair_play_points
            else v_discipline.yellow_fair_play_points end
        when event.event_type = 'red_card' then v_discipline.red_fair_play_points
        else 0
      end)::integer fair_play
    from public.tournament_projection_sources source
    join public.tournament_match_events event
      on event.match_operation_id = source.match_operation_id and event.voided_at is null
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
      and outcome.events_remain_valid
    where source.revision_id = v_revision.id
    group by event.team_entry_id
  ), aggregated as (
    select participant.id participant_id, participant.team_entry_id,
      count(team_match.*)::integer played,
      count(*) filter (where team_match.gf > team_match.ga)::integer won,
      count(*) filter (where team_match.gf = team_match.ga)::integer drawn,
      count(*) filter (where team_match.gf < team_match.ga)::integer lost,
      coalesce(sum(team_match.gf), 0)::integer gf,
      coalesce(sum(team_match.ga), 0)::integer ga,
      coalesce(sum(case
        when team_match.gf > team_match.ga
          and team_match.outcome_type like 'walkover_%'
          then coalesce(v_scoring.points_walkover_win, v_scoring.points_win)
        when team_match.gf < team_match.ga
          and team_match.outcome_type like 'walkover_%'
          then coalesce(v_scoring.points_walkover_loss, v_scoring.points_loss)
        when team_match.gf > team_match.ga then v_scoring.points_win
        when team_match.gf = team_match.ga then v_scoring.points_draw
        else v_scoring.points_loss
      end), 0)::integer base_points,
      count(*) filter (where team_match.outcome_type like 'walkover_%')::integer walkovers,
      count(*) filter (where team_match.outcome_type = 'administrative_result')::integer administrative
    from participants participant
    left join team_matches team_match on team_match.participant_id = participant.id
    group by participant.id, participant.team_entry_id
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, aggregated.participant_id, aggregated.team_entry_id,
    aggregated.played, aggregated.won, aggregated.drawn, aggregated.lost,
    aggregated.gf, aggregated.ga, aggregated.gf - aggregated.ga,
    aggregated.base_points,
    coalesce(adjustment.points, 0),
    aggregated.base_points + coalesce(adjustment.points, 0),
    aggregated.walkovers, aggregated.administrative,
    coalesce(cards.fair_play, 0)
  from aggregated
  left join cards on cards.team_entry_id = aggregated.team_entry_id
  left join lateral (
    select sum(points)::integer points
    from public.tournament_points_adjustments
    where organization_id = p_organization_id
      and tournament_id = p_tournament_id and category_id = p_category_id
      and participant_set_id = v_fixture.participant_set_id
      and fixture_version_id = v_fixture.id
      and phase_id = p_phase_id and group_id is not distinct from p_group_id
      and participant_id = aggregated.participant_id and status = 'active'
  ) adjustment on true;

  perform public.rank_tournament_standings(v_revision.id);

  insert into public.tournament_player_statistics (
    revision_id, organization_id, tournament_id, category_id,
    roster_player_id, team_entry_id, squad_calls, appearances, starts,
    substitute_appearances, goals, own_goals, assists, penalty_goals,
    penalties_missed, yellow_cards, second_yellows, red_cards, captaincies
  )
  with players as (
    select operation_player.roster_player_id, operation_player.team_entry_id,
      count(distinct operation_player.match_operation_id)::integer squad_calls,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.attendance_status in ('present', 'late'))::integer appearances,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.lineup_status = 'starter'
          and operation_player.attendance_status in ('present', 'late'))::integer starts,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.lineup_status = 'substitute'
          and operation_player.attendance_status in ('present', 'late'))::integer substitutes,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.is_captain
          and operation_player.attendance_status in ('present', 'late'))::integer captaincies
    from public.tournament_projection_sources source
    join public.tournament_match_operation_players operation_player
      on operation_player.match_operation_id = source.match_operation_id
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_player_stats
    group by operation_player.roster_player_id, operation_player.team_entry_id
  ), events as (
    select event.roster_player_id,
      count(*) filter (
        where event.event_type in ('goal', 'penalty_goal')
          and not (event.event_type = 'penalty_goal' and event.period = 'penalties')
      )::integer goals,
      count(*) filter (where event.event_type = 'own_goal')::integer own_goals,
      count(*) filter (where event.event_type = 'assist')::integer assists,
      count(*) filter (where event.event_type = 'penalty_goal'
        and event.period <> 'penalties')::integer penalty_goals,
      count(*) filter (where event.event_type = 'penalty_missed')::integer penalties_missed,
      count(*) filter (where event.event_type = 'yellow_card')::integer yellow_cards,
      count(*) filter (where event.event_type = 'second_yellow')::integer second_yellows,
      count(*) filter (where event.event_type = 'red_card')::integer red_cards
    from public.tournament_projection_sources source
    join public.tournament_match_events event
      on event.match_operation_id = source.match_operation_id and event.voided_at is null
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_player_stats
      and outcome.events_remain_valid
      and event.roster_player_id is not null
    group by event.roster_player_id
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    player.roster_player_id, player.team_entry_id, player.squad_calls,
    player.appearances, player.starts, player.substitutes,
    coalesce(event.goals, 0), coalesce(event.own_goals, 0),
    coalesce(event.assists, 0), coalesce(event.penalty_goals, 0),
    coalesce(event.penalties_missed, 0), coalesce(event.yellow_cards, 0),
    coalesce(event.second_yellows, 0), coalesce(event.red_cards, 0),
    player.captaincies
  from players player
  left join events event on event.roster_player_id = player.roster_player_id;

  insert into public.tournament_team_statistics (
    revision_id, organization_id, participant_id, team_entry_id, goals,
    own_goals_benefited, yellow_cards, second_yellows, red_cards,
    home_played, away_played, suspended_matches, administrative_matches
  )
  select v_revision.id, p_organization_id, standing.participant_id,
    standing.team_entry_id, standing.goals_for,
    (select count(*)::integer
      from public.tournament_projection_sources source
      join public.tournament_match_events event
        on event.match_operation_id = source.match_operation_id
        and event.voided_at is null
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = source.match_operation_id
        and outcome.events_remain_valid
      where source.revision_id = v_revision.id
        and event.event_type = 'own_goal'
        and event.team_entry_id = standing.team_entry_id),
    coalesce(sum(player_stats.yellow_cards), 0)::integer,
    coalesce(sum(player_stats.second_yellows), 0)::integer,
    coalesce(sum(player_stats.red_cards), 0)::integer,
    (select count(*)::integer from public.tournament_projection_sources source
      join public.tournament_matches match_row on match_row.id = source.match_id
      where source.revision_id = v_revision.id
        and match_row.home_participant_id = standing.participant_id),
    (select count(*)::integer from public.tournament_projection_sources source
      join public.tournament_matches match_row on match_row.id = source.match_id
      where source.revision_id = v_revision.id
        and match_row.away_participant_id = standing.participant_id),
    (select count(*)::integer from public.tournament_projection_sources source
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = source.match_operation_id
      join public.tournament_match_operations operation
        on operation.id = source.match_operation_id
      where source.revision_id = v_revision.id
        and outcome.outcome_type = 'suspended'
        and standing.team_entry_id in (
          operation.home_team_entry_id, operation.away_team_entry_id
        )),
    standing.administrative_results
  from public.tournament_team_standings standing
  left join public.tournament_player_statistics player_stats
    on player_stats.revision_id = standing.revision_id
    and player_stats.team_entry_id = standing.team_entry_id
  where standing.revision_id = v_revision.id
  group by standing.participant_id, standing.team_entry_id, standing.goals_for,
    standing.administrative_results;

  with form as (
    select standing.participant_id,
      source.official_at,
      case
        when (
          match_row.home_participant_id = standing.participant_id
          and score.home_score > score.away_score
        ) or (
          match_row.away_participant_id = standing.participant_id
          and score.away_score > score.home_score
        ) then 'W'
        when score.home_score = score.away_score then 'D'
        else 'L'
      end result,
      row_number() over (
        partition by standing.participant_id
        order by source.official_at desc, source.match_id
      ) form_order
    from public.tournament_team_standings standing
    join public.tournament_projection_sources source
      on source.revision_id = standing.revision_id
    join public.tournament_matches match_row
      on match_row.id = source.match_id
      and standing.participant_id in (
        match_row.home_participant_id, match_row.away_participant_id
      )
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
      and outcome.counts_for_standings
    join public.tournament_match_scores score
      on score.match_operation_id = source.match_operation_id
    where standing.revision_id = v_revision.id
  ), form_with_first as (
    select form.*,
      first_value(result) over (
        partition by participant_id order by form_order
      ) first_result
    from form
  ), streaks as (
    select form_with_first.*,
      sum(case when result = first_result then 0 else 1 end) over (
        partition by participant_id order by form_order
      ) break_count
    from form_with_first
  ), summary as (
    select participant_id,
      jsonb_agg(result order by form_order) filter (where form_order <= 5) recent_form,
      max(case when form_order = 1 then result end) first_result,
      count(*) filter (where break_count = 0)::integer streak_count
    from streaks
    group by participant_id
  )
  update public.tournament_team_statistics stats
  set recent_form = coalesce(summary.recent_form, '[]'::jsonb),
    streak_type = case summary.first_result
      when 'W' then 'win' when 'D' then 'draw' when 'L' then 'loss' end,
    streak_count = summary.streak_count
  from summary
  where stats.revision_id = v_revision.id
    and stats.participant_id = summary.participant_id;

  -- Never execute DML on a caller-owned temporary relation under elevated privileges.
  if pg_catalog.to_regclass('pg_temp.tournament_discipline_event_work') is not null then
    drop table pg_temp.tournament_discipline_event_work;
  end if;
  create temporary table pg_temp.tournament_discipline_event_work (
    event_id uuid primary key,
    match_operation_id uuid not null,
    match_id uuid not null,
    phase_id uuid not null,
    phase_sequence integer not null,
    official_at timestamptz not null,
    match_number integer not null,
    team_entry_id uuid not null,
    roster_player_id uuid not null,
    event_type text not null,
    sequence_number integer not null
  ) on commit drop;
  truncate pg_temp.tournament_discipline_event_work;

  insert into pg_temp.tournament_discipline_event_work (
    event_id, match_operation_id, match_id, phase_id, phase_sequence,
    official_at, match_number, team_entry_id, roster_player_id,
    event_type, sequence_number
  )
  select event.id, operation.id, match_row.id, match_row.phase_id,
    match_phase.sequence_number, operation.official_at, match_row.match_number,
    event.team_entry_id, event.roster_player_id, event.event_type,
    event.sequence_number
  from public.tournament_matches match_row
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id and outcome.events_remain_valid
  join public.tournament_match_events event
    on event.match_operation_id = operation.id and event.voided_at is null
  join public.tournament_team_standings current_team
    on current_team.revision_id = v_revision.id
    and current_team.team_entry_id = event.team_entry_id
  where match_row.fixture_version_id = v_fixture.id
    and match_phase.sequence_number <= v_phase.sequence_number
    and (
      not v_discipline.reset_yellows_each_stage
      or match_row.phase_id = p_phase_id
    )
    and (
      match_row.phase_id <> p_phase_id
      or match_row.group_id is not distinct from p_group_id
    )
    and event.roster_player_id is not null
    and event.event_type in ('yellow_card', 'second_yellow', 'red_card');

  insert into public.tournament_discipline_ledgers (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    roster_player_id, team_entry_id, yellow_cards, second_yellows, direct_reds,
    fair_play_points, automatic_suspensions
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, event.roster_player_id, event.team_entry_id,
    count(*) filter (where event.event_type = 'yellow_card')::integer,
    count(*) filter (where event.event_type = 'second_yellow')::integer,
    count(*) filter (where event.event_type = 'red_card')::integer,
    (
      count(*) filter (where event.event_type = 'yellow_card')
        * v_discipline.yellow_fair_play_points
      + count(*) filter (where event.event_type = 'second_yellow')
        * case when v_discipline.double_yellow_counts_as_red
          then v_discipline.red_fair_play_points
          else v_discipline.yellow_fair_play_points end
      + count(*) filter (where event.event_type = 'red_card')
        * v_discipline.red_fair_play_points
    )::integer,
    floor((
      count(*) filter (where event.event_type = 'yellow_card')
    )::numeric / v_discipline.yellows_for_suspension)::integer
      + count(*) filter (where event.event_type = 'red_card')::integer
      + case when v_discipline.double_yellow_counts_as_red
        then count(*) filter (where event.event_type = 'second_yellow')::integer
        else 0 end
  from pg_temp.tournament_discipline_event_work event
  group by event.roster_player_id, event.team_entry_id;

  insert into public.tournament_player_suspensions (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    roster_player_id, team_entry_id, source_type, source_key, source_event_id,
    source_match_id, rule_snapshot, total_matches, reason
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, threshold_event.roster_player_id,
    threshold_event.team_entry_id,
    'yellow_accumulation', 'yellow:' || threshold_event.event_id::text,
    threshold_event.event_id, threshold_event.match_id,
    jsonb_build_object(
      'threshold', v_discipline.yellows_for_suspension,
      'matches', v_discipline.suspension_matches,
      'yellowNumber', threshold_event.yellow_number,
      'resetEachStage', v_discipline.reset_yellows_each_stage
    ),
    v_discipline.suspension_matches,
    'Acumulación de ' || v_discipline.yellows_for_suspension::text || ' amarillas'
  from (
    select yellow_event.*,
      row_number() over (
        partition by yellow_event.roster_player_id
        order by yellow_event.phase_sequence, yellow_event.official_at,
          yellow_event.match_number, yellow_event.sequence_number, yellow_event.event_id
      )::integer yellow_number
    from pg_temp.tournament_discipline_event_work yellow_event
    where yellow_event.event_type = 'yellow_card'
  ) threshold_event
  where threshold_event.phase_id = p_phase_id
    and threshold_event.yellow_number % v_discipline.yellows_for_suspension = 0;

  insert into public.tournament_player_suspensions (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    roster_player_id, team_entry_id, source_type, source_key, source_event_id,
    source_match_id, rule_snapshot, total_matches, reason
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, event.roster_player_id, event.team_entry_id,
    case when event.event_type = 'red_card' then 'direct_red' else 'second_yellow' end,
    event.match_id::text || ':' || event.event_type || ':' ||
      event.sequence_number::text,
    event.event_id, event.match_id,
    jsonb_build_object(
      'eventType', event.event_type,
      'matches', case when event.event_type = 'red_card'
        then coalesce(v_discipline.direct_red_suggested_matches, v_discipline.suspension_matches)
        else v_discipline.suspension_matches end
    ),
    case when event.event_type = 'red_card'
      then coalesce(v_discipline.direct_red_suggested_matches, v_discipline.suspension_matches)
      else v_discipline.suspension_matches end,
    case when event.event_type = 'red_card' then 'Roja directa' else 'Segunda amarilla' end
  from pg_temp.tournament_discipline_event_work event
  where event.phase_id = p_phase_id
    and (
      event.event_type = 'red_card'
      or (event.event_type = 'second_yellow' and v_discipline.double_yellow_counts_as_red)
    );

  if v_fingerprint <> public.tournament_projection_source_fingerprint(
    v_fixture.id, p_phase_id, p_group_id
  ) then
    raise exception using errcode = '40001', message = 'TORNEOS_STANDINGS_SOURCES_CHANGED';
  end if;

  perform public.append_tournament_audit(
    p_organization_id, 'standings.rebuild', 'standings_revision',
    v_revision.id, null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id, 'phaseId', p_phase_id,
      'groupId', p_group_id, 'revisionNumber', v_number,
      'sourceFingerprint', v_fingerprint, 'reason', btrim(p_reason)
    )
  );
  return v_revision.id;
end;
$function$;

-- public.record_manual_match_availability(uuid,uuid,uuid,text,text,text): POST_0005 body
CREATE OR REPLACE FUNCTION public.record_manual_match_availability(p_organization_id uuid, p_match_id uuid, p_roster_player_id uuid, p_response text, p_reason text, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_player public.tournament_roster_players%rowtype;
  v_response public.tournament_match_availability_responses%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_response not in ('available', 'unavailable', 'maybe')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 500
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AVAILABILITY';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for share;
  select player.* into v_player
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id
    and roster.status in ('approved', 'locked')
  where player.id = p_roster_player_id
    and player.organization_id = p_organization_id
    and player.status = 'active'
    and player.eligibility_status = 'eligible';
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_match.scheduled_at is null or now() >= v_match.scheduled_at
    or v_player.id is null
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, v_player.team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:match-availability:' || p_match_id || ':' || v_player.id, 0
  ));
  insert into public.tournament_match_availability_responses (
    organization_id, match_id, team_entry_id, roster_player_id, user_id,
    response, comment, response_source, recorded_by, manual_reason
  ) values (
    p_organization_id, p_match_id, v_player.team_entry_id, v_player.id,
    v_player.arma2_user_id, p_response, nullif(btrim(p_comment), ''),
    'manual', private.current_identity_id(), btrim(p_reason)
  )
  on conflict (match_id, roster_player_id) do update set
    response = excluded.response, comment = excluded.comment,
    user_id = excluded.user_id, response_source = 'manual',
    recorded_by = excluded.recorded_by, manual_reason = excluded.manual_reason,
    responded_at = now(), updated_at = now()
  where public.tournament_match_availability_responses.response_source = 'manual'
  returning * into v_response;
  if v_response.id is null then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_AVAILABILITY_SELF_AUTHORITATIVE';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match_availability.recorded_manual',
    'match_availability', v_response.id, v_player.team_entry_id,
    v_match.tournament_id, jsonb_build_object('response', p_response, 'source', 'manual')
  );
  return jsonb_build_object('id', v_response.id, 'response', v_response.response);
end;
$function$;

-- public.resolve_tournament_qualification(uuid,text): POST_0005 body
CREATE OR REPLACE FUNCTION public.resolve_tournament_qualification(p_revision_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_revision public.tournament_standings_revisions%rowtype;
  v_source public.tournament_match_sources%rowtype;
  v_slot public.tournament_qualification_slots%rowtype;
  v_participant uuid;
  v_existing uuid;
  v_count integer := 0;
  v_blocked integer := 0;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_revision from public.tournament_standings_revisions
  where id = p_revision_id and status = 'published' for share;
  if v_revision.id is null or not (public.has_tournament_organization_capability(
    v_revision.organization_id, 'qualification.resolve'
  ) and public.has_tournament_season_access(v_revision.organization_id, v_revision.season_id)) then
    raise exception using errcode = '42501', message = 'TORNEOS_QUALIFICATION_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_QUALIFICATION_REASON_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_revision.organization_id::text || ':' || v_revision.tournament_id::text || ':'
    || v_revision.category_id::text || ':' || v_revision.phase_id::text || ':'
    || coalesce(v_revision.group_id::text, 'all'),
    0
  ));
  if exists (
    select 1 from public.tournament_matches match_row
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and match_row.status <> 'cancelled'
      and (
        match_row.home_participant_id is null
        or match_row.away_participant_id is null
        or not exists (
          select 1
          from public.tournament_match_operations operation
          join public.tournament_match_outcomes outcome
            on outcome.match_operation_id = operation.id
            and outcome.counts_for_standings
            and not outcome.requires_resolution
          where operation.match_id = match_row.id
            and operation.status = 'official'
        )
      )
  ) or exists (
    select 1 from public.tournament_match_outcomes outcome
    join public.tournament_match_operations operation
      on operation.id = outcome.match_operation_id and operation.status = 'official'
    join public.tournament_matches match_row on match_row.id = operation.match_id
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and outcome.requires_resolution
  ) or exists (
    select 1
    from public.tournament_match_reviews review
    join public.tournament_match_operations operation
      on operation.id = review.match_operation_id
    join public.tournament_matches match_row on match_row.id = operation.match_id
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and review.status = 'open'
      and review.review_type in (
        'correction', 'dispute_future', 'administrative_resolution'
      )
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_INCOMPLETE';
  end if;
  if exists (
    select 1 from public.tournament_team_standings standing
    where standing.revision_id = v_revision.id
      and standing.classification_status = 'manual_review'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_AMBIGUOUS';
  end if;

  for v_source in
    select source.*
    from public.tournament_match_sources source
    where source.fixture_version_id = v_revision.fixture_version_id
      and (
        (source.source_type = 'group_position'
          and source.group_id is not distinct from v_revision.group_id)
        or (source.source_type = 'league_position'
          and source.source_phase_id = v_revision.phase_id)
        or (
          source.source_type in ('winner_of_match', 'loser_of_match')
          and exists (
            select 1 from public.tournament_matches source_match
            where source_match.id = source.source_match_id
              and source_match.phase_id = v_revision.phase_id
              and source_match.group_id is not distinct from v_revision.group_id
          )
        )
      )
    order by source.match_id, source.side
  loop
    if v_source.source_type in ('winner_of_match', 'loser_of_match') then
      select case
        when v_source.source_type = 'winner_of_match' then
          case when score.home_score > score.away_score
              or (
                score.home_score = score.away_score
                and score.home_penalties > score.away_penalties
              )
            then source_match.home_participant_id
            when score.away_score > score.home_score
              or (
                score.home_score = score.away_score
                and score.away_penalties > score.home_penalties
              )
            then source_match.away_participant_id end
        else
          case when score.home_score < score.away_score
              or (
                score.home_score = score.away_score
                and score.home_penalties < score.away_penalties
              )
            then source_match.home_participant_id
            when score.away_score < score.home_score
              or (
                score.home_score = score.away_score
                and score.away_penalties < score.home_penalties
              )
            then source_match.away_participant_id end
        end
      into v_participant
      from public.tournament_matches source_match
      join public.tournament_match_operations operation
        on operation.match_id = source_match.id and operation.status = 'official'
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = operation.id
        and not outcome.requires_resolution
      join public.tournament_match_scores score
        on score.match_operation_id = operation.id
      where source_match.id = v_source.source_match_id;
    else
      select standing.participant_id into v_participant
      from public.tournament_team_standings standing
      where standing.revision_id = v_revision.id
        and standing.position = coalesce(
          v_source.position_number, v_source.rank_number
        );
    end if;
    if v_participant is null then
      raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_AMBIGUOUS';
    end if;

    insert into public.tournament_qualification_slots (
      organization_id, tournament_id, category_id, fixture_version_id,
      source_phase_id, source_group_id, match_source_id, slot_type, rank_number
    ) values (
      v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
      v_revision.fixture_version_id, v_revision.phase_id, v_revision.group_id,
      v_source.id, v_source.source_type,
      coalesce(v_source.position_number, v_source.rank_number, 1)
    )
    on conflict (match_source_id) do update set status = 'active'
    returning * into v_slot;

    select case when v_source.side = 'home'
      then match_row.home_participant_id else match_row.away_participant_id end
    into v_existing
    from public.tournament_matches match_row
    where match_row.id = v_source.match_id
    for update;

    if exists (
      select 1
      from public.tournament_qualification_resolutions resolution
      where resolution.slot_id = v_slot.id
        and resolution.status = 'manual'
    ) then
      raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_MANUAL_LOCKED';
    end if;

    if v_existing is not null and v_existing <> v_participant and exists (
      select 1 from public.tournament_match_operations operation
      where operation.match_id = v_source.match_id
    ) then
      update public.tournament_qualification_resolutions
      set status = 'superseded', superseded_at = now()
      where slot_id = v_slot.id and status in ('resolved', 'blocked', 'manual');

      insert into public.tournament_qualification_resolutions (
        organization_id, tournament_id, category_id, fixture_version_id,
        standings_revision_id, slot_id, participant_id, target_match_id,
        target_side, status, reason, resolved_by
      ) values (
        v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
        v_revision.fixture_version_id, v_revision.id, v_slot.id, v_participant,
        v_source.match_id, v_source.side, 'blocked',
        'El cruce posterior ya tiene un acta y requiere resolución manual.',
        private.current_identity_id()
      )
      on conflict do nothing;
      v_blocked := v_blocked + 1;
      continue;
    end if;

    update public.tournament_qualification_resolutions
    set status = 'superseded', superseded_at = now()
    where slot_id = v_slot.id and status in ('resolved', 'blocked', 'manual');

    insert into public.tournament_qualification_resolutions (
      organization_id, tournament_id, category_id, fixture_version_id,
      standings_revision_id, slot_id, participant_id, target_match_id,
      target_side, status, reason, resolved_by
    ) values (
      v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
      v_revision.fixture_version_id, v_revision.id, v_slot.id, v_participant,
      v_source.match_id, v_source.side, 'resolved', btrim(p_reason), private.current_identity_id()
    );

    update public.tournament_matches
    set home_participant_id = case when v_source.side = 'home'
        then v_participant else home_participant_id end,
      away_participant_id = case when v_source.side = 'away'
        then v_participant else away_participant_id end,
      updated_at = now()
    where id = v_source.match_id;
    v_count := v_count + 1;
  end loop;

  perform public.append_tournament_audit(
    v_revision.organization_id, 'qualification.resolve', 'standings_revision',
    v_revision.id, null, v_revision.tournament_id,
    jsonb_build_object('resolved', v_count, 'blocked', v_blocked, 'reason', btrim(p_reason))
  );
  return jsonb_build_object('resolved', v_count, 'blocked', v_blocked);
end;
$function$;

-- public.review_tournament_match_operation(uuid,uuid,text,text): POST_0005 body
CREATE OR REPLACE FUNCTION public.review_tournament_match_operation(p_organization_id uuid, p_match_operation_id uuid, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_review public.tournament_match_reviews%rowtype;
  v_outcome_type text;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status not in ('submitted', 'under_review')
    or p_decision not in ('approved', 'rejected')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 2000
    or not (public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.review'
    ) and public.has_tournament_season_access(p_organization_id, (select o.season_id from public.tournament_match_operations o where o.id = p_match_operation_id and o.organization_id = p_organization_id)))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_review from public.tournament_match_reviews
  where match_operation_id = v_operation.id and review_type = 'validation'
    and status = 'open' for update;
  if v_review.id is null then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_REVIEW_NOT_OPEN';
  end if;
  update public.tournament_match_reviews set
    status = p_decision, resolved_by = private.current_identity_id(), resolved_at = now(),
    resolution = btrim(p_reason)
  where id = v_review.id;
  select outcome_type into v_outcome_type
  from public.tournament_match_outcomes
  where match_operation_id = v_operation.id;
  update public.tournament_match_operations set
    status = case when p_decision = 'approved' then 'under_review' else 'draft' end,
    match_status = case when p_decision = 'approved' then match_status else
      case
        when v_outcome_type = 'played' then 'played'
        when v_outcome_type = 'suspended' then 'suspended'
        when v_outcome_type = 'abandoned' then 'abandoned'
        when v_outcome_type in (
          'home_no_show', 'away_no_show', 'double_no_show',
          'walkover_home', 'walkover_away', 'administrative_result'
        ) then 'administrative'
        else 'ready'
      end end,
    submitted_by = case when p_decision = 'approved' then submitted_by else null end,
    submitted_at = case when p_decision = 'approved' then submitted_at else null end,
    updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.reviewed', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('decision', p_decision)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$;

-- public.save_match_squad(uuid,uuid,uuid,jsonb): POST_0005 body
CREATE OR REPLACE FUNCTION public.save_match_squad(p_organization_id uuid, p_match_id uuid, p_team_entry_id uuid, p_players jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_squad public.tournament_match_squads%rowtype;
  v_player jsonb;
  v_roster_player public.tournament_roster_players%rowtype;
  v_team_size integer;
  v_substitutes_limit integer;
  v_starters integer;
  v_captains integer;
  v_called_up integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_players, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_players, '[]'::jsonb)) > 80
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, p_team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status in ('approved', 'locked')
  order by version desc limit 1;
  if v_roster.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ROSTER_NOT_APPROVED';
  end if;
  select coalesce(category.team_size, tournament.team_size),
    coalesce(tournament.substitutes_limit, tournament.team_size)
  into v_team_size, v_substitutes_limit
  from public.tournament_categories category
  join public.tournaments tournament on tournament.id = category.tournament_id
  where category.id = v_match.category_id;
  select count(*) filter (where value->>'lineupStatus' = 'starter'),
    count(*) filter (where coalesce((value->>'isCaptain')::boolean, false)),
    count(*) filter (where value->>'callupStatus' = 'called_up')
  into v_starters, v_captains, v_called_up
  from jsonb_array_elements(p_players);
  if v_starters > v_team_size or v_captains > 1
    or v_called_up > v_team_size + v_substitutes_limit
  then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  insert into public.tournament_match_squads (
    organization_id, match_id, team_entry_id, roster_id, created_by
  ) values (
    p_organization_id, p_match_id, p_team_entry_id, v_roster.id, private.current_identity_id()
  )
  on conflict (match_id, team_entry_id) where status <> 'superseded'
  do update set updated_at = now()
  returning * into v_squad;
  if v_squad.status <> 'draft' then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_SQUAD_LOCKED';
  end if;
  delete from public.tournament_match_squad_players
  where match_squad_id = v_squad.id;
  for v_player in select value from jsonb_array_elements(p_players)
  loop
    select * into v_roster_player
    from public.tournament_roster_players
    where id = (v_player->>'rosterPlayerId')::uuid
      and roster_id = v_roster.id and team_entry_id = p_team_entry_id
      and status = 'active' and eligibility_status = 'eligible';
    if v_roster_player.id is null then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_OUT_OF_SCOPE';
    end if;
    insert into public.tournament_match_squad_players (
      organization_id, match_squad_id, match_id, roster_player_id, team_entry_id,
      availability_status, callup_status, lineup_status, shirt_number_snapshot,
      position_snapshot, display_name_snapshot, avatar_url_snapshot,
      is_goalkeeper, is_captain, attendance_status
    ) values (
      p_organization_id, v_squad.id, p_match_id, v_roster_player.id, p_team_entry_id,
      coalesce((
        select availability.response
        from public.tournament_match_availability_responses availability
        where availability.match_id = p_match_id
          and availability.roster_player_id = v_roster_player.id
      ), 'no_response'),
      coalesce(v_player->>'callupStatus', 'not_called_up'),
      coalesce(v_player->>'lineupStatus', 'not_in_match_squad'),
      v_roster_player.shirt_number, v_roster_player.primary_position,
      v_roster_player.display_name, v_roster_player.avatar_url,
      v_roster_player.is_goalkeeper,
      coalesce((v_player->>'isCaptain')::boolean, false),
      coalesce(v_player->>'attendanceStatus', 'unknown')
    );
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'match_squad.saved', 'match_squad', v_squad.id,
    p_team_entry_id, v_match.tournament_id,
    jsonb_build_object('players', jsonb_array_length(p_players))
  );
  return public.get_match_squad_context(p_organization_id, p_match_id, p_team_entry_id);
end;
$function$;

-- public.set_tournament_announcement_audience(uuid,text,uuid,uuid,uuid,uuid): POST_0005 body
CREATE OR REPLACE FUNCTION public.set_tournament_announcement_audience(p_announcement_id uuid, p_audience_type text, p_category_id uuid DEFAULT NULL::uuid, p_team_entry_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_specific_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not (public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    ) and public.has_tournament_season_access(v_announcement.organization_id, v_announcement.season_id))
    or (
      v_announcement.author_user_id <> private.current_identity_id()
      and not (public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      ) and public.has_tournament_season_access(v_announcement.organization_id, v_announcement.season_id))
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_audiences audience
      where audience.announcement_id = p_announcement_id) >= 12
  then
    raise exception using errcode = '54000', message = 'TORNEOS_AUDIENCE_LIMIT_REACHED';
  end if;
  if p_audience_type = 'category' and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = v_announcement.organization_id
      and category.tournament_id = v_announcement.tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type = 'team' and not exists (
    select 1 from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.organization_id = v_announcement.organization_id
      and entry.tournament_id = v_announcement.tournament_id
      and entry.status = 'approved'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type in ('match','home_team','away_team') and not exists (
    select 1 from public.tournament_matches match
    join public.tournament_fixture_versions fixture
      on fixture.id = match.fixture_version_id
     and fixture.organization_id = match.organization_id
     and fixture.status = 'published'
    where match.id = p_match_id
      and match.organization_id = v_announcement.organization_id
      and match.tournament_id = v_announcement.tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  end if;

  insert into public.tournament_announcement_audiences (
    organization_id,announcement_id,audience_type,category_id,team_entry_id,
    match_id,specific_user_id,created_by
  ) values (
    v_announcement.organization_id,p_announcement_id,p_audience_type,
    p_category_id,p_team_entry_id,p_match_id,p_specific_user_id,private.current_identity_id()
  )
  on conflict on constraint tournament_announcement_audiences_unique
  do update set created_by = excluded.created_by
  returning id into v_id;
  return v_id;
end;
$function$;

-- public.set_tournament_announcement_link(uuid,text,uuid,text,text,integer): POST_0005 body
CREATE OR REPLACE FUNCTION public.set_tournament_announcement_link(p_announcement_id uuid, p_link_type text, p_resource_id uuid, p_external_url text, p_label text, p_sort_order integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
  v_valid boolean := false;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not (public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    ) and public.has_tournament_season_access(v_announcement.organization_id, v_announcement.season_id))
    or (
      v_announcement.author_user_id <> private.current_identity_id()
      and not (public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      ) and public.has_tournament_season_access(v_announcement.organization_id, v_announcement.season_id))
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_links link
      where link.announcement_id = p_announcement_id) >= 5
  then
    raise exception using errcode = '54000', message = 'TORNEOS_LINK_LIMIT_REACHED';
  end if;
  if p_link_type = 'external' then
    v_valid := p_external_url ~
      '^https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?(?:/[^[:space:]]*)?$';
  elsif p_link_type = 'tournament' then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'category' then
    v_valid := exists (
      select 1 from public.tournament_categories category
      where category.id = p_resource_id
        and category.organization_id = v_announcement.organization_id
        and category.tournament_id = v_announcement.tournament_id
        and category.status = 'active'
    );
  elsif p_link_type = 'match' then
    v_valid := exists (
      select 1 from public.tournament_matches match
      join public.tournament_fixture_versions fixture
        on fixture.organization_id = match.organization_id
       and fixture.id = match.fixture_version_id
       and fixture.status = 'published'
      where match.id = p_resource_id
        and match.organization_id = v_announcement.organization_id
        and match.tournament_id = v_announcement.tournament_id
    );
  elsif p_link_type in ('round','standings','discipline') then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'document' then
    v_valid := exists (
      select 1 from public.tournament_documents document
      where document.id = p_resource_id
        and document.organization_id = v_announcement.organization_id
        and document.tournament_id = v_announcement.tournament_id
        and document.status = 'published'
    );
  end if;
  if not v_valid then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  insert into public.tournament_announcement_links (
    organization_id,announcement_id,link_type,resource_id,external_url,label,sort_order
  ) values (
    v_announcement.organization_id,p_announcement_id,p_link_type,p_resource_id,
    nullif(btrim(coalesce(p_external_url,'')),''),btrim(p_label),p_sort_order
  )
  on conflict (announcement_id,sort_order) do update
  set link_type = excluded.link_type,resource_id = excluded.resource_id,
    external_url = excluded.external_url,label = excluded.label
  returning id into v_id;
  return v_id;
end;
$function$;

-- public.set_tournament_match_dual_control(uuid,uuid,boolean): POST_0005 body
CREATE OR REPLACE FUNCTION public.set_tournament_match_dual_control(p_organization_id uuid, p_tournament_id uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_state jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_enabled is null then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DUAL_CONTROL';
  end if;
  select * into v_tournament from public.tournaments
  where id = p_tournament_id and organization_id = p_organization_id for update;
  if v_tournament.id is null or not (
    public.has_tournament_organization_capability(p_organization_id, 'match_operations.configure_dual_control')
    and public.has_tournament_season_access(p_organization_id, v_tournament.season_id)
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if v_tournament.status in ('completed', 'archived') then
    raise exception using errcode = '22023', message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;
  v_state := public.get_tournament_match_dual_control(p_organization_id, p_tournament_id);
  if v_tournament.match_result_dual_control_enabled = p_enabled then
    return v_state;
  end if;
  -- Turning it ON with a single eligible validator would block every result of this tournament.
  if p_enabled and (v_state->>'eligibleValidators')::integer < 2 then
    raise exception using errcode = 'P0001', message = 'TORNEOS_DUAL_CONTROL_SECOND_VALIDATOR_REQUIRED';
  end if;
  update public.tournaments set match_result_dual_control_enabled = p_enabled
  where id = v_tournament.id;
  perform public.append_tournament_audit(
    p_organization_id, 'tournament.match_dual_control_changed', 'tournament', v_tournament.id,
    null, v_tournament.id,
    jsonb_build_object('enabled', p_enabled, 'previous', v_tournament.match_result_dual_control_enabled)
  );
  return public.get_tournament_match_dual_control(p_organization_id, p_tournament_id);
end;
$function$;

DO $post$
DECLARE
  v_pins text[][] := array[
    array['public.append_tournament_playoff_phase(uuid,uuid,uuid,uuid,integer,boolean,uuid)', '996cb4f6fc49524fbda06f16227bc472', '1166ca6ba0811a83c688ed8c6d8c828c'],
    array['public.create_tournament_announcement_draft(uuid,uuid,uuid,text,text,text,text,text,text,timestamp with time zone,uuid,text,uuid)', '02eaa14aef6b3a9e709935e28232fe1b', 'f2f2dd910245f8ebb0c8ca2fd8448f19'],
    array['public.create_tournament_match_correction(uuid,uuid)', 'e951e5be55e80835906f355360398590', 'd0e27384efd5b70f5ef1baf9893ecf30'],
    array['public.request_tournament_match_correction(uuid,uuid,text)', '6cbfbe91fb54eafca64520456e700a1a', 'ea194c20129c58a1581ff0804ca362dd'],
    array['public.mark_tournament_suspension_served(uuid,uuid,text)', '179376cfb1cd940d64ffa7dc34c40dc6', '0ca29ae1d9e55671dc3cdd9d18d83efd'],
    array['public.protect_active_tournament_fixture_draft()', 'c067a91075ab2dd5f6b0d114b694286f', '4aef5269146750bfe579910f7772447f'],
    array['public.protect_tournament_completed_competition()', '94012caa5505b8845a21ea247d26a496', 'f3f77a153eab65aef37046c65b891698'],
    array['public.protect_tournament_match_squad_players()', 'd6a8eb923c378bbe47ceb4ee77a4f164', '517664b2b2e325b42af98731f5ec4366'],
    array['public.publish_tournament_announcement(uuid,integer)', '7b5de1040a89810b8a09055087d56519', 'e5e6d5e9c2e0acf73548209a0e265c80'],
    array['public.publish_tournament_fixture(uuid,uuid)', 'b730e3eda644554c36dca95eafb6bbce', '2c64761a38d28e5fbdcd5735fb0a76b2'],
    array['public.rebuild_tournament_standings(uuid,uuid,uuid,uuid,uuid,text,uuid)', '647d3a01d3489af7111afa6017e9dba3', '1cd1dbdabeae82ea7d6e0c9a7fce37c0'],
    array['public.record_manual_match_availability(uuid,uuid,uuid,text,text,text)', '63f7fb5c744586172f56043487225ca7', '1acdb4e53b05f3a8cb3c5a9b98bdfb3b'],
    array['public.resolve_tournament_qualification(uuid,text)', '3f1af0ba733eacf51bc868542c150c73', '193a69bf4fb8e95047015a9b9da3e9cd'],
    array['public.review_tournament_match_operation(uuid,uuid,text,text)', '6f5912e4cf6601ad1d8301ed61bf7adc', '840710c77dc6343c2232b4c6590c946f'],
    array['public.save_match_squad(uuid,uuid,uuid,jsonb)', 'b95278f07e0ce51fc297f3324ef1600a', '931d2820b0711135eb2365b50e95f303'],
    array['public.set_tournament_announcement_audience(uuid,text,uuid,uuid,uuid,uuid)', '9d00a52f2abea44a7d020f3db7a9ffe7', '7d7bbe6ba33b95a9fb601b3129b902d9'],
    array['public.set_tournament_announcement_link(uuid,text,uuid,text,text,integer)', 'b20a2f8a60d793fd8ab09ede3f7d7b4c', '8ff92a71f5efa6167556e5297f8b5cf1'],
    array['public.set_tournament_match_dual_control(uuid,uuid,boolean)', '0379096408e86030361fa2390fcf02b1', '631be35793594b6641529ded5b91c055']
  ];
  v_problems text[] := array[]::text[];
  v_before torneos_error_contract_v1_rollback_acl%rowtype;
  v_auth integer;
  v_anon integer;
  i integer;
BEGIN
  FOR i IN 1 .. array_length(v_pins, 1) LOOP
    IF (SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = to_regprocedure(v_pins[i][1])) IS DISTINCT FROM v_pins[i][2] THEN
      v_problems := v_problems || ('body not restored: ' || v_pins[i][1]);
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM torneos_error_contract_v1_rollback_state s JOIN pg_proc p ON p.oid = to_regprocedure(s.fn)
             WHERE s.attrs IS DISTINCT FROM concat_ws('|', pg_get_userbyid(p.proowner), coalesce(p.proacl::text, 'default'), p.prosecdef, coalesce(p.proconfig::text, ''), p.provolatile, p.proparallel, p.proretset, p.prorettype::regtype, p.prokind, p.prolang)) THEN
    v_problems := v_problems || 'owner / ACL / definer / config / signature of a restored function changed'::text;
  END IF;
  SELECT * INTO v_before FROM torneos_error_contract_v1_rollback_acl;
  SELECT count(*) FILTER (WHERE has_function_privilege('authenticated', p.oid, 'EXECUTE')),
         count(*) FILTER (WHERE has_function_privilege('anon', p.oid, 'EXECUTE'))
    INTO v_auth, v_anon
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.prokind = 'f';
  IF v_auth <> v_before.authenticated_public OR v_anon <> v_before.anon_public THEN
    v_problems := v_problems || 'client catalog changed'::text;
  END IF;
  IF cardinality(v_problems) > 0 THEN
    RAISE EXCEPTION 'TORNEOS_ERROR_CONTRACT_V1_ROLLBACK_POSTCONDITION_FAILED: %', array_to_string(v_problems, '; ');
  END IF;
END $post$;

COMMIT;
